package com.example.starter.waste;

import java.time.Clock;
import java.time.ZoneId;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 台账时间源配置：统一使用 Asia/Shanghai 时区时钟，测试可替换为可控时钟。
 */
@Configuration
public class WasteConfig {

    /**
     * 业务时钟，所有称重、回执、日结时间均取自该时钟。
     */
    @Bean
    public Clock businessClock() {
        return Clock.system(ZoneId.of("Asia/Shanghai"));
    }
}

package com.example.starter.waste;

/**
 * 联单状态：IN_PROGRESS 执行中；CLOSED 回执闭环；EXCEPTION 偏差异常核查中。
 */
public enum ManifestStatus {
    IN_PROGRESS,
    CLOSED,
    EXCEPTION
}

package com.example.starter.waste;

/**
 * 异常核查结论分类：DEVICE_ERROR 设备误差；LOADING_DIFF 装载差异。
 */
public enum ConclusionType {
    DEVICE_ERROR,
    LOADING_DIFF
}

package com.example.starter.waste;

import org.springframework.http.HttpStatus;

/**
 * 台账业务异常，携带 HTTP 状态与稳定错误码，由全局异常处理器转换为响应体。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }
}

package com.example.starter.waste;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;

/**
 * 幂等指纹工具：对 requestId 与全部业务字段的规范化拼接计算 SHA-256。
 */
public final class Fingerprints {

    private Fingerprints() {
    }

    /**
     * 计算指纹；字段按传入顺序以竖线拼接，null 统一为空串。
     */
    public static String of(List<String> fields) {
        String canonical = String.join("|", fields.stream().map(f -> f == null ? "" : f).toList());
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(canonical.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(hash.length * 2);
            for (byte b : hash) {
                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
                hex.append(Character.forDigit(b & 0xF, 16));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 unavailable", e);
        }
    }
}

